const uniqueProvinceName=(mode:NameMode,index:number,r:RNG,used:Set<string>)=>{const real=chooseDatabase(mode,r),pool=real?REAL_PROVINCES:FICTIONAL_PROVINCES;const base=pool[index%pool.length];const qualifiers=real?['North','South','East','West','Upper','Lower','Greater','Lesser','New','Old','High','Coastal','Central']:['Northern','Southern','Eastern','Western','Upper','Lower','Greater','Lesser','New','Old','High','Coastal','Central'];let name=base;if(used.has(name)){for(const q of qualifiers){const candidate=`${q} ${base}`;if(!used.has(candidate)){name=candidate;break}}}if(used.has(name)){const second=pool[(index*7+13)%pool.length];name=`${base}-${second}`;if(used.has(name)){for(const q of qualifiers){const candidate=`${q} ${base}-${second}`;if(!used.has(candidate)){name=candidate;break}}}}used.add(name);return name};
const politicalCoreName=(c:Civilization,s:WorldState)=>{
  const capital=s.cities.find(x=>x.id===c.capitalCityId)?.name;
  const last=[...c.nameHistory].reverse().find(h=>!['Tribe','Settlement'].includes(h.rank))?.name;
  return (last??capital??c.originTribe)
    .replace(/^(Duchy of |Kingdom of |Greater |Lesser |Eastern |Western |Northern |Southern )/,'')
    .replace(/ Empire$/,'')
    .replace(/ Settlements?$/,'')
    .replace(/ian$/,'ia')
    .replace(/ean$/,'ea');
};
