function ensureModernGlobalContact(s:WorldState){
  if(s.year<1900)return;
  const living=s.civilizations.filter(c=>c.provinces.length);
  const continentIds=s.continents.map(c=>c.id);
  const realmIds=living.map(c=>c.id);
  const incomplete=living.some(c=>continentIds.some(id=>!c.knownContinentIds.includes(id)));
  if(!incomplete)return;
  for(const c of living){c.knownContinentIds=[...continentIds];c.knownRealmIds=realmIds.filter(id=>id!==c.id)}
  addEvent(s,'exploration','The world becomes fully connected','By 1900 CE, navigation, diplomacy and accumulated geographic knowledge connected every inhabited continent. All surviving realms now know of one another.',10,realmIds,{continentIds,technologyIds:['deep_sailing'],tags:['global contact','connected world'],worldChronicle:true});
}

