export function advanceWorld(w:WorldState,years:number){const s=structuredClone(w),r=new RNG((s.seed+s.year*31+years*911)>>>0);for(let i=0;i<years;i++){simulateYear(s,r);for(const c of s.civilizations){if(!Number.isFinite(c.population)||!Number.isFinite(c.gdp)||!Number.isFinite(c.technology)||!Number.isFinite(c.armySize)||!Number.isFinite(c.armyCapacity)){c.population=Math.max(0,Number.isFinite(c.population)?c.population:0);c.gdp=Math.max(.1,Number.isFinite(c.gdp)?c.gdp:.1);c.technology=Math.max(0,Math.min(1000,Number.isFinite(c.technology)?c.technology:0));c.armyCapacity=Math.max(0,Number.isFinite(c.armyCapacity)?c.armyCapacity:0);c.armySize=Math.max(0,Math.min(c.armyCapacity,Number.isFinite(c.armySize)?c.armySize:0))}}}return s}

export function runBalanceTest(seed=424242,years=5000){let world=createWorld({name:'Balance Test',mapSize:'medium',mapVariant:1,tribeCount:36,nameMode:'mixed'},seed);world=advanceWorld(world,years);const alive=world.civilizations.filter(c=>c.provinces.length);return{year:world.year,population:alive.reduce((n,c)=>n+c.population,0),maxTechnology:Math.max(...alive.map(c=>c.technology)),medianGDP:[...alive].sort((a,b)=>a.gdp-b.gdp)[Math.floor(alive.length/2)]?.gdp??0,empires:alive.filter(c=>c.rank==='Empire').length,people:world.people.length,livingPeople:world.people.filter(p=>p.active).length,religions:world.religions.length,wars:world.wars.length,battles:world.battles.length,wonders:world.wonders.length,cities:world.cities.length};}
